package plates.core.values

/** A plain rectangle; the one Rect type of the model. */
public data class Rect(val left: Double, val top: Double, val right: Double, val bottom: Double) {
    val width: Double get() = right - left
    val height: Double get() = bottom - top

    public companion object {
        public fun fromLTRB(left: Double, top: Double, right: Double, bottom: Double): Rect = Rect(left, top, right, bottom)

        public fun fromLTWH(left: Double, top: Double, width: Double, height: Double): Rect =
            Rect(left, top, left + width, top + height)
    }
}

/** A point in a drawing's coordinate space. */
public data class Point(val x: Double, val y: Double)

/** Colors are ARGB32 ints. */
public typealias Color = Int

public fun Color(argb: Long): Color = argb.toInt()

/**
 * A rectangle in plate coordinates: origin at the plate's top-left, units
 * shared with PlateSpec.canvasWidth and canvasHeight.
 */
public data class PlateBox(val left: Double, val top: Double, val width: Double, val height: Double) {
    val right: Double get() = left + width
    val bottom: Double get() = top + height
    val rect: Rect get() = Rect.fromLTWH(left, top, width, height)
}
